function rapGen(theme, mood, rng){
  theme=String(theme||'').trim(); if(!theme) return {error:'请填写主题'};
  rng=rng||Math.random; mood=mood||'燃';
  var open=['Yo，听好，','上来了，','麦克风交给我，','节拍起，'];
  var mid=[''+theme+' 是我的信仰','把 '+theme+' 写进每一行',''+theme+' 燃爆全场',''+theme+' 不讲假话',''+theme+' 是王者的勋章','让 '+theme+' 在街头回响'];
  var close=['这波 flow 你接得住吗','收工，下一段更炸','记住这个名字，'+theme];
  var lines=[open[Math.floor(rng()*open.length)]];
  var need=4+Math.floor(rng()*3), used={};
  while(lines.length-1<need){ var i=Math.floor(rng()*mid.length); if(!used[i]){used[i]=1; lines.push(mid[i]);} else if(Object.keys(used).length>=mid.length) break; }
  lines.push(close[Math.floor(rng()*close.length)]);
  return {lines:lines, theme:theme, mood:mood};
}
var EXPORTS={rapGen:rapGen};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RapForgePure = EXPORTS; }
